function compute(p) {
  var Q = p.Q, K = p.K, V = p.V;
  var nq = Q.length, nk = K.length, dk = Q[0].length, dv = V[0].length;
  var T = p.temperature > 0 ? p.temperature : 1;
  var denom = p.scale ? Math.sqrt(dk) : 1;
  var S = [], Z = [], A = [], O = [];
  var warning = null;
  for (var i = 0; i < nq; i++) {
    var srow = [], zrow = [];
    for (var j = 0; j < nk; j++) {
      var s = 0;
      for (var d = 0; d < dk; d++) s += Q[i][d] * K[j][d];
      srow.push(s);
      zrow.push(s / denom / T);
    }
    S.push(srow); Z.push(zrow);
    var m = -Infinity;
    for (var j2 = 0; j2 < nk; j2++) if (zrow[j2] > m) m = zrow[j2];
    var ex = [], sum = 0;
    for (var j3 = 0; j3 < nk; j3++) { var e = Math.exp(zrow[j3] - m); ex.push(e); sum += e; }
    var arow = [];
    for (var j4 = 0; j4 < nk; j4++) arow.push(ex[j4] / sum);
    A.push(arow);
    var orow = [];
    for (var c = 0; c < dv; c++) {
      var acc = 0;
      for (var j5 = 0; j5 < nk; j5++) acc += arow[j5] * V[j5][c];
      orow.push(acc);
    }
    O.push(orow);
  }
  var rowSums = [];
  for (var i2 = 0; i2 < nq; i2++) { var rs = 0; for (var j6 = 0; j6 < nk; j6++) rs += A[i2][j6]; rowSums.push(rs); }
  var maxAbsZ = 0;
  for (var i3 = 0; i3 < nq; i3++) for (var j7 = 0; j7 < nk; j7++) { var v = Math.abs(Z[i3][j7]); if (v > maxAbsZ) maxAbsZ = v; }
  var maxWeight = 0;
  for (var i4 = 0; i4 < nq; i4++) for (var j8 = 0; j8 < nk; j8++) if (A[i4][j8] > maxWeight) maxWeight = A[i4][j8];
  var qLabels = [], kLabels = [], vLabels = [];
  for (var i5 = 0; i5 < nq; i5++) qLabels.push('q' + (i5 + 1));
  for (var j9 = 0; j9 < nk; j9++) kLabels.push('k' + (j9 + 1));
  for (var j10 = 0; j10 < nk; j10++) vLabels.push('v' + (j10 + 1));
  var flatA = [];
  for (var i6 = 0; i6 < nq; i6++) for (var j11 = 0; j11 < nk; j11++) flatA.push(A[i6][j11]);
  var flatZ = [];
  for (var i7 = 0; i7 < nq; i7++) for (var j12 = 0; j12 < nk; j12++) flatZ.push(Z[i7][j12]);
  var flatLabels = [];
  for (var i8 = 0; i8 < nq; i8++) for (var j13 = 0; j13 < nk; j13++) flatLabels.push('q' + (i8 + 1) + '->k' + (j13 + 1));
  var Ocol0 = [], Ocol1 = [];
  for (var i9 = 0; i9 < nq; i9++) { Ocol0.push(O[i9][0]); Ocol1.push(O[i9][1]); }
  return {
    S: S, Z: Z, A: A, O: O,
    Ocol0: Ocol0, Ocol1: Ocol1,
    rowSums: rowSums,
    maxAbsZ: maxAbsZ,
    maxWeight: maxWeight,
    dk: dk, dv: dv, nq: nq, nk: nk,
    denom: denom,
    qLabels: qLabels, kLabels: kLabels, vLabels: vLabels,
    flatA: flatA, flatZ: flatZ, flatLabels: flatLabels,
    warning: warning
  };
}
